// Normalizador de datos: soporta payload directo desde el POS (JSON) o desde Telegram
const inputData = $input.item.json.body || $input.item.json;

if (inputData.nombre_cliente) {
  // 1. Limpiar cédula para evitar duplicar el 'V-' que ya tiene la plantilla de Google Docs
  let cedulaLimpia = String(inputData.cedula_cliente || '').trim();
  cedulaLimpia = cedulaLimpia.replace(/^[vV]-?/, '');

  // 2. Limpiar precio: si viene con '.00', quitarlo para que encaje con ',00$' de la plantilla
  let precioLimpio = String(inputData.precio || '').trim();
  if (precioLimpio.includes('.')) {
    const partes = precioLimpio.split('.');
    if (partes[1] === '00' || partes[1] === '0') {
      precioLimpio = partes[0];
    }
  }

  // 3. Garantía
  const meses = String(inputData.garantia_meses || 3);
  const dias = String(inputData.garantia_dias || (parseInt(meses, 10) * 30));

  return [{
    json: {
      nombre_cliente: inputData.nombre_cliente,
      telefono_cliente: inputData.telefono_cliente,
      cedula_cliente: cedulaLimpia,
      ubicacion: inputData.ubicacion,
      metodo_pago: inputData.metodo_pago,
      correo: inputData.correo || 'ventas@zendroxtech.com',
      precio: precioLimpio,
      modelo: inputData.modelo,
      numero_orden: inputData.numero_orden,
      fecha_hoy: inputData.fecha_hoy,
      meses: meses,
      dias: dias
    }
  }];
}

// Fallback si por alguna razón viniera texto plano
if (inputData.message && inputData.message.text) {
  const lineas = inputData.message.text.split('\n');
  if (lineas.length >= 10) {
    let cedulaLimpia = lineas[2].trim().replace(/^[vV]-?/, '');
    let precioLimpio = lineas[6].trim();
    if (precioLimpio.includes('.')) {
      const partes = precioLimpio.split('.');
      if (partes[1] === '00' || partes[1] === '0') precioLimpio = partes[0];
    }
    return [{
      json: {
        nombre_cliente: lineas[0],
        telefono_cliente: lineas[1],
        cedula_cliente: cedulaLimpia,
        ubicacion: lineas[3],
        metodo_pago: lineas[4],
        correo: lineas[5],
        precio: precioLimpio,
        modelo: lineas[7],
        numero_orden: lineas[8],
        fecha_hoy: lineas[9],
        meses: '3',
        dias: '90'
      }
    }];
  }
}

throw new Error('Formato de datos de venta no válido.');

